allow:
# 在庫の API（https://api.example）。画面のサイト（https://shop.example）のブラウザから呼ばれる
server {
  listen 443 ssl;
  server_name api.example;
  ssl_certificate /etc/nginx/certs/api.crt;

  location / {
    add_header Access-Control-Allow-Origin "https://shop.example";
    proxy_pass http://127.0.0.1:3000;
  }
}

server {
    listen 443 ssl;
    server_name api.example;
    ssl_certificate /etc/nginx/certs/api.crt;

    location / {
        proxy_pass http://127.0.0.1:3000;
        add_header 'Access-Control-Allow-Origin' 'https://shop.example' always;
    }
}

input:
server {
  listen 443 ssl;
  server_name api.example;
  ssl_certificate /etc/nginx/certs/api.crt;

  location / {
    proxy_pass http://127.0.0.1:3000;
    add_header Access-Control-Allow-Origin *;
  }
}
